if (!loaded() || !valid_height(pixel_height) || left < 0 || right < 0 ||
    left >= impl_->info.numGlyphs || right >= impl_->info.numGlyphs)
    return std::nullopt;
const float scale = stbtt_ScaleForPixelHeight(&impl_->info, pixel_height);
return stbtt_GetGlyphKernAdvance(&impl_->info, left, right) * scale;

const float pen_x = pen_ + kern_before;
const float new_pen = pen_x + advance;
// 수량·유한성·수치 범위와 사각형 검증 후
items_[count_++] = {pen_x, baseline_};
pen_ = new_pen;
line_widths_[lines_ - 1] = pen_;

line_widths_[lines_ - 1] = pen_;
++lines_;
baseline_ += line_advance();
pen_ = 0;
previous_ = false;

const float x0 = std::min(old.x, placed.x);
const float y0 = std::min(old.y, placed.y);
const float x1 = std::max(old.x + old.w, placed.x + placed.w);
const float y1 = std::max(old.y + old.h, placed.y + placed.h);
ink_ = Box{x0, y0, x1-x0, y1-y0};

line_widths_[lines_ - 1] = pen_;
// result()
float widest = 0;
for (std::size_t i=0; i<lines_; ++i)
    widest = std::max(widest, line_widths_[i]);
out.width = widest;

const auto kern = layout.has_previous()
    ? font.kerning(previous, glyph->index, height) : std::optional<float>(0);
if (!kern || !layout.add(glyph->advance, *kern,
    {float(glyph->xoff),float(glyph->yoff),float(glyph->width),float(glyph->height)}))
    return std::nullopt;
previous = glyph->index;
paragraph.items[paragraph.count++].glyph = std::move(*glyph);

const auto& measured = app.screen()==study_app::Screen::menu
    ? *menu_pixels : *play_label_pixels;
const float label_x = 14+(64-measured.layout.width)/2;
if (!label.draw(text_quad,label_x,82)) return 1;

if (previous)
    line_width += stbtt_GetCodepointKernAdvance(
        &s_font, (int)previous, (int)cp) * scale;
int advance = 0, bearing = 0;
stbtt_GetCodepointHMetrics(&s_font, (int)cp, &advance, &bearing);
line_width += advance * scale;
